# problem P-5d88c3 (generated by sonnet): For a Sidon set $S\subseteq\mathbb N_0$ let $S(x)=|S\cap[0,x]|$. Pilatte proved that some Sidon set $S$ is an asymptotic basis of order 3, i.e. every large integer is a sum of three elements of $S$ (repetitions allowed). Is there such a Sidon basis of order 3 with $S(x)\ge x^{1/2-\varepsilon}$ for e
# finite_form: Find a Sidon set $S\subseteq\{0,1,\dots,200\}$ with $|S|\le 12$ such that every integer $n$ with $70\le n\le 200$ is a sum of three elements of $S$ (repetitions allowed).
# candidate_format: A JSON array of distinct integers in [0,200], at most 12 of them.

def check(candidate):
    try:
        if not isinstance(candidate, list):
            return False
        if len(candidate) > 12 or len(candidate) == 0:
            return False
        for x in candidate:
            if type(x) is not int or x < 0 or x > 200:
                return False
        if len(set(candidate)) != len(candidate):
            return False
        S = sorted(candidate)
        sums = set()
        for i in range(len(S)):
            for j in range(i, len(S)):
                s = S[i] + S[j]
                if s in sums:
                    return False
                sums.add(s)
        three = set()
        for a in S:
            for b in S:
                for c in S:
                    three.add(a + b + c)
        for n in range(70, 201):
            if n not in three:
                return False
        return True
    except Exception:
        return False